INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('8040b3ca-8cce-4c4e-8e65-840a0d18de35', 'c1c2c3d4-3030-4000-8000-000000000030', 3, 'Sentir', 'Semana 1 — Despertar', '{"pch": "Sentir n\u00e3o \u00e9 fraqueza\u2026 \u00e9 acesso.", "verse": "Sl 34,18", "lectio": "Leia o vers\u00edculo e pergunte: onde est\u00e1 essa dor em mim agora?", "practice": "Nomeie tr\u00eas emo\u00e7\u00f5es que voc\u00ea sentiu hoje, sem julgamento.", "question": "O que voc\u00ea evita sentir?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;